-- ----------------------------
-- Table structure for inventory
-- ----------------------------
DROP TABLE IF EXISTS `inventory`;
CREATE TABLE `inventory`  (
  `id` bigint NOT NULL COMMENT '涓婚敭ID',
  `sku_id` bigint NOT NULL COMMENT '鍟嗗搧SKU ID',
  `total_stock` int NOT NULL DEFAULT 0 COMMENT '鎬诲簱瀛',
  `locked_stock` int NOT NULL DEFAULT 0 COMMENT '閿佸畾搴撳瓨锛堥?鍗犳湭鎵ｅ噺锛',
  `available_stock` int NOT NULL DEFAULT 0 COMMENT '鍙?敤搴撳瓨',
  `safety_stock` int NOT NULL DEFAULT 10 COMMENT '瀹夊叏搴撳瓨锛堥?璀﹂槇鍊硷級',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '鏇存柊鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_sku_id`(`sku_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '搴撳瓨琛' ROW_FORMAT = Dynamic;

