-- ----------------------------
-- Table structure for inventory_log
-- ----------------------------
DROP TABLE IF EXISTS `inventory_log`;
CREATE TABLE `inventory_log`  (
  `id` bigint NOT NULL COMMENT '涓婚敭ID',
  `sku_id` bigint NOT NULL COMMENT '鍟嗗搧SKU ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鍏宠仈璁㈠崟鍙',
  `change_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '鍙樻洿绫诲瀷锛歀OCK-棰勫崰 DEDUCT-鎵ｅ噺 RELEASE-閲婃斁 ADD-琛ヨ揣 INIT-鍒濆?鍖',
  `change_count` int NOT NULL COMMENT '鍙樻洿鏁伴噺',
  `before_stock` int NOT NULL COMMENT '鍙樻洿鍓嶅簱瀛',
  `after_stock` int NOT NULL COMMENT '鍙樻洿鍚庡簱瀛',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '鍒涘缓鏃堕棿',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_sku_id`(`sku_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '搴撳瓨鍙樻洿鏃ュ織琛' ROW_FORMAT = Dynamic;

