-- ----------------------------
-- Table structure for order_item
-- ----------------------------
DROP TABLE IF EXISTS `order_item`;
CREATE TABLE `order_item`  (
  `id` bigint NOT NULL COMMENT 'item_id',
  `order_id` bigint NOT NULL COMMENT 'order_id',
  `seller_id` bigint NOT NULL DEFAULT 0 COMMENT '下单时商品所属商家用户ID，0表示平台自营',
  `seller_order_id` bigint NULL DEFAULT NULL COMMENT '鍟嗗?瀛愯?鍗旾D',
  `spu_id` bigint NOT NULL COMMENT 'spu_id',
  `sku_id` bigint NOT NULL COMMENT 'sku_id',
  `product_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'product_name',
  `product_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'product_image',
  `price` decimal(10, 2) NOT NULL COMMENT 'unit_price',
  `quantity` int NOT NULL DEFAULT 1 COMMENT 'quantity',
  `total_price` decimal(10, 2) NOT NULL COMMENT 'total_price',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_order_id`(`order_id` ASC) USING BTREE,
  INDEX `idx_order_item_seller_order`(`seller_id` ASC, `order_id` ASC) USING BTREE,
  INDEX `idx_order_item_seller_order_id`(`seller_order_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'order_item' ROW_FORMAT = Dynamic;

