-- ----------------------------
-- Table structure for seller_order_t
-- ----------------------------
DROP TABLE IF EXISTS `seller_order_t`;
CREATE TABLE `seller_order_t`  (
  `id` bigint NOT NULL COMMENT '鍟嗗?瀛愯?鍗旾D',
  `order_id` bigint NOT NULL COMMENT '涔板?涓昏?鍗旾D',
  `seller_id` bigint NOT NULL COMMENT '鍟嗗?鐢ㄦ埛ID',
  `seller_amount` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '璇ュ晢瀹跺晢鍝侀噾棰',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '0寰呮敮浠?1宸叉敮浠?2宸插彂璐?3宸插畬鎴?4宸插彇娑',
  `shipping_company` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鐗╂祦鍏?徃',
  `tracking_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '杩愬崟鍙',
  `ship_time` datetime NULL DEFAULT NULL COMMENT '鍙戣揣鏃堕棿',
  `receive_time` datetime NULL DEFAULT NULL COMMENT '鏀惰揣鏃堕棿',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_seller_order_order_seller`(`order_id` ASC, `seller_id` ASC) USING BTREE,
  INDEX `idx_seller_order_seller_status_time`(`seller_id` ASC, `status` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_seller_order_order_id`(`order_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '鍟嗗?瀛愯?鍗曡〃' ROW_FORMAT = Dynamic;

